    int i;
    adcs_vec3_t cur, pw, nxt;
    double v[3], rr[3], t[3];

    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    t[0] = temperature->x; t[1] = temperature->y; t[2] = temperature->z;
    v[0] = voltage->x; v[1] = voltage->y; v[2] = voltage->z;
    rr[0] = resistance->x; rr[1] = resistance->y; rr[2] = resistance->z;

    for (i = 0; i < 3; i++) {
        if ((!isfinite(t[i])) || (!isfinite(v[i])) || (!isfinite(rr[i])) || (rr[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }
    }
    if ((!isfinite(ambient)) || (!isfinite(thermal_capacity)) || (!isfinite(thermal_resistance)) ||
        (thermal_capacity <= 0.0) || (thermal_resistance <= 0.0)) {
        return ADCS_E_RANGE;
    }
    if ((!isfinite(dt)) || (dt < 0.0)) {
        return ADCS_E_RANGE;
    }

    for (i = 0; i < 3; i++) {
        double ii = v[i] / rr[i];
        double pi = (v[i] * v[i]) / rr[i];
        if (i == 0) {
            cur.x = ii; pw.x = pi;
            nxt.x = t[i] + dt * (pi - (t[i] - ambient) / thermal_resistance) / thermal_capacity;
        } else if (i == 1) {
            cur.y = ii; pw.y = pi;
            nxt.y = t[i] + dt * (pi - (t[i] - ambient) / thermal_resistance) / thermal_capacity;
        } else {
            cur.z = ii; pw.z = pi;
            nxt.z = t[i] + dt * (pi - (t[i] - ambient) / thermal_resistance) / thermal_capacity;
        }
    }

    *current = cur;
    *power = pw;
    *next_temperature = nxt;
    *total_power = pw.x + pw.y + pw.z;

    return ADCS_OK;
}

